import fs from 'node:fs';
import path from 'node:path';
import { createHash, randomUUID } from 'node:crypto';

const fingerprint = (messages: unknown[]) => createHash('sha256').update(JSON.stringify(messages)).digest('hex');

// Legacy missing-key notices were generated by the HTTP error handler, not Pi.
// Never use a generic "not found in context" fallback for real conversations.
export function isServerNotice(message: any, projected: any[] = []) {
  if (message.role !== 'agent') return false;
  if (message.origin === 'server-error') return true;
  const legacy = /^[^:\n]+: No API key found for [\w-]+\.\s+Use \/login to log into a provider/.test(message.text);
  return legacy && !projected.some(m => m.role === 'agent' && m.text === message.text);
}

export function createTranscriptDeletion(file: string) {
  function load(): Record<string, any> {
    try { return JSON.parse(fs.readFileSync(file, 'utf8')); }
    catch (error: any) { if (error.code === 'ENOENT') return {}; throw error; }
  }
  function save(records: Record<string, any>) {
    fs.mkdirSync(path.dirname(file), { recursive: true });
    fs.writeFileSync(file + '.tmp', JSON.stringify(records), { mode: 0o600 });
    fs.renameSync(file + '.tmp', file);
  }
  return {
    record(session: string, message: any, index: number, remaining: any[]) {
      const records = load();
      const token = 'web-' + randomUUID();
      records[token] = { session, message, index, fingerprint: fingerprint(remaining) };
      save(records);
      return token;
    },
    restore(session: string, token: string, messages: any[]) {
      const records = load();
      const record = records[token];
      if (!record || record.session !== session) throw new Error('Deletion not found in this conversation.');
      if (record.fingerprint !== fingerprint(messages)) throw new Error('Cannot restore after the conversation has changed.');
      delete records[token];
      save(records);
      return { message: record.message, index: record.index };
    }
  };
}
